import "reflect-metadata";
import { getDataSource } from "@/lib/db/dataSource";
import { TaskService } from "@/lib/services/TaskService";
import { TaskStatus } from "@/lib/db/enums";

const POLL_INTERVAL_MS = 5000;

class WorkerService {
  private taskService: TaskService;

  constructor(taskService: TaskService) {
    this.taskService = taskService;
  }

  async processNext(): Promise<void> {
    const ds = await getDataSource();

    await ds.transaction(async (em) => {
      const task = await em
        .createQueryBuilder()
        .select("task")
        .from("tasks", "task")
        .where("task.status = :status", { status: TaskStatus.QUEUED })
        .setLock("pessimistic_write_or_fail")
        .getOne();

      if (!task) return;

      await em.update("tasks", task.id, { status: TaskStatus.PROCESSING });
      console.log(`[worker] picked up task ${task.id}`);

      // TODO: invoke InvoiceAgent (Task 6)
      // For now just mark as failed with a placeholder message
      await this.taskService.updateStatus(
        task.id,
        TaskStatus.FAILED,
        "Agent not yet implemented"
      );
    });
  }

  start(): void {
    console.log("[worker] starting, polling every", POLL_INTERVAL_MS, "ms");
    const poll = async () => {
      try {
        await this.processNext();
      } catch (err) {
        console.error("[worker] error:", err);
      } finally {
        setTimeout(poll, POLL_INTERVAL_MS);
      }
    };
    poll();
  }
}

async function main() {
  await getDataSource();
  const taskService = new TaskService();
  const worker = new WorkerService(taskService);
  worker.start();
}

main().catch((err) => {
  console.error("[worker] fatal:", err);
  process.exit(1);
});

